export const LANGS = [
  { id: "zh", label: "中" },
  { id: "ja", label: "日" },
  { id: "en", label: "EN" },
];

export const tr = (code, lang = "zh") => {
  if (code === undefined || code === null) return "";
  const entry = LABELS[code];
  if (!entry) return code;
  return entry[lang] || entry.zh || code;
};

export const LangContext = createContext("zh");
export const useLang = () => useContext(LangContext);
